'use client';

import { useState, useEffect, useRef, useCallback } from 'react';
import Webcam from 'react-webcam';
import { motion, AnimatePresence, useAnimation } from 'framer-motion';
import { Wifi, MessageSquare, BarChart, Sliders, Wind, RefreshCw, CloudOff, AlertTriangle, Video, VideoOff, Edit2, Zap } from 'lucide-react';
import { useEmotionSocket } from '../hooks/useEmotionSocket';
import { emotionStyles, Emotion } from '../lib/emotionStyles';
import BreathingGuide from '../components/BreathingGuide';
import AnimatedQuote from '../components/AnimatedQuote';

// --- Type Definitions ---
type Quote = { quote: string; author: string };

// --- Fallback Quotes ---
const fallbackQuotes: Record<Emotion, Quote[]> = {
    happy: [{ quote: "The purpose of our lives is to be happy.", author: "Dalai Lama" }],
    sad: [{ quote: "Tears come from the heart and not from the brain.", author: "Leonardo da Vinci" }],
    angry: [{ quote: "For every minute you remain angry, you give up sixty seconds of peace of mind.", author: "Ralph Waldo Emerson" }],
    fear: [{ quote: "The only thing we have to fear is fear itself.", author: "Franklin D. Roosevelt" }],
    surprise: [{ quote: "The world is full of magical things patiently waiting for our wits to grow sharper.", author: "Bertrand Russell" }],
    disgust: [{ quote: "Disgust is the appropriate reaction to most of the news.", author: "Ambrose Bierce" }],
    neutral: [{ quote: "The mind is everything. What you think you become.", author: "Buddha" }],
};

// --- Particle Component ---
const Particle = () => {
    const duration = Math.random() * 5 + 5;
    const delay = Math.random() * 3;
    const initialX = Math.random() * 100;
    const initialY = Math.random() * 100;
    const finalY = initialY + (Math.random() > 0.5 ? -1 : 1) * (Math.random() * 15 + 10);
    const finalX = initialX + (Math.random() > 0.5 ? -1 : 1) * (Math.random() * 15 + 10);

    return (
        <motion.circle
            cx={`${initialX}%`}
            cy={`${initialY}%`}
            r={Math.random() * 1.5 + 0.5}
            fill="rgba(255, 255, 255, 0.3)"
            animate={{
                cy: [`${initialY}%`, `${finalY}%`, `${initialY}%`],
                cx: [`${initialX}%`, `${finalX}%`, `${initialX}%`],
            }}
            transition={{
                duration,
                delay,
                repeat: Infinity,
                ease: "easeInOut"
            }}
        />
    );
};

// --- Daily Intention Component ---
const DailyIntention = () => {
  const [intention, setIntention] = useState(() => {
    if (typeof window !== 'undefined') {
      return localStorage.getItem('dailyIntention') || "What is your focus for today?";
    }
    return "What is your focus for today?";
  });
  const [isEditing, setIsEditing] = useState(false);

  useEffect(() => {
    if (typeof window !== 'undefined') {
      localStorage.setItem('dailyIntention', intention);
    }
  }, [intention]);

  return (
    <motion.div 
      className="absolute bottom-8 left-8 max-w-sm p-4 rounded-xl bg-white/5 border border-white/10 backdrop-blur-md shadow-lg"
      initial={{ opacity: 0, x: -50 }}
      animate={{ opacity: 1, x: 0, transition: { delay: 0.5, duration: 0.8, ease: [0.16, 1, 0.3, 1] } }}
      exit={{ opacity: 0, x: -50 }}
    >
      <div className="flex justify-between items-center mb-2">
        <h3 className="text-sm font-semibold text-white/70">Daily Intention</h3>
        <button onClick={() => setIsEditing(!isEditing)} className="text-white/50 hover:text-white transition-colors">
            <Edit2 size={14} />
        </button>
      </div>
      {isEditing ? (
        <input
          type="text"
          value={intention}
          onChange={(e) => setIntention(e.target.value)}
          onBlur={() => setIsEditing(false)}
          onKeyDown={(e) => e.key === 'Enter' && setIsEditing(false)}
          className="w-full bg-transparent text-lg italic border-b border-white/30 focus:outline-none focus:border-white transition-colors"
          autoFocus
        />
      ) : (
        <p onClick={() => setIsEditing(true)} className="text-lg italic cursor-pointer min-h-[28px]">
          {intention}
        </p>
      )}
    </motion.div>
  );
};

// --- Emotion Simulator Component ---
const EmotionSimulator = ({ onSelect, activeEmotion }: { onSelect: (emotion: Emotion) => void, activeEmotion: Emotion }) => {
    const emotions: Emotion[] = ['happy', 'sad', 'angry', 'fear', 'surprise', 'neutral'];
    return (
        <motion.div
            className="absolute bottom-10 flex items-center justify-center w-full"
            initial={{ opacity: 0, y: 50 }}
            animate={{ opacity: 1, y: 0, transition: { delay: 0.5, duration: 0.8, ease: [0.16, 1, 0.3, 1] } }}
            exit={{ opacity: 0, y: 50 }}
        >
            <div className="flex gap-4 p-3 rounded-full bg-white/5 border border-white/10 backdrop-blur-md shadow-lg">
                {emotions.map(emo => (
                    <motion.button
                        key={emo}
                        onClick={() => onSelect(emo)}
                        className={`w-12 h-12 rounded-full flex items-center justify-center transition-all duration-300 relative`}
                        style={{
                            background: activeEmotion === emo ? (emotionStyles[emo]?.orbColor || 'rgba(255,255,255,0.1)') : 'rgba(255,255,255,0.1)',
                            border: activeEmotion === emo ? '2px solid rgba(255,255,255,0.8)' : '2px solid transparent'
                        }}
                        whileHover={{ scale: 1.15 }}
                        whileTap={{ scale: 0.95 }}
                    >
                        <span className="text-xs font-bold capitalize">{emo}</span>
                    </motion.button>
                ))}
            </div>
        </motion.div>
    );
}

export default function HomePage() {
  const webcamRef = useRef<Webcam>(null);
  const { emotion: liveEmotion, isConnected, sendFrame } = useEmotionSocket('http://127.0.0.1:5000');
  
  const [currentQuote, setCurrentQuote] = useState<Quote>({ quote: "Activate the Bio-Sensor or explore the dashboard.", author: "MindMorph" });
  const [isQuoteLoading, setIsQuoteLoading] = useState(false);
  const [showBreathingGuide, setShowBreathingGuide] = useState(false);
  const stressTimerRef = useRef<NodeJS.Timeout | null>(null);
  const [hasMounted, setHasMounted] = useState(false);
  const [apiStatus, setApiStatus] = useState<'online' | 'offline'>('online');
  const [isWebcamActive, setIsWebcamActive] = useState(false);
  
  const [simulatedEmotion, setSimulatedEmotion] = useState<Emotion>('neutral');
  const emotion = isWebcamActive ? liveEmotion : simulatedEmotion;

  useEffect(() => { setHasMounted(true); }, []);

  const fetchQuotes = useCallback(async (currentEmotion: Emotion) => {
    setIsQuoteLoading(true);
    try {
        const tags = {happy: 'happiness', sad: 'sadness', angry: 'wisdom', fear: 'courage', surprise: 'imagination', neutral: 'technology'}[currentEmotion] || 'inspirational';
        const response = await fetch(`https://api.quotable.io/quotes/random?limit=1&tags=${tags}`);
        if (!response.ok) throw new Error("API failed");
        const data = await response.json();
        if (data && data.length > 0) {
            setCurrentQuote({ quote: data[0].content, author: data[0].author });
            setApiStatus('online');
        } else {
            throw new Error("No quotes found for tag");
        }
    } catch (error) {
        console.warn("API fetch failed, using fallback.", error);
        setCurrentQuote(fallbackQuotes[currentEmotion][0] || fallbackQuotes.neutral[0]);
        setApiStatus('offline');
    } finally {
        setIsQuoteLoading(false);
    }
  }, []);

  useEffect(() => {
    fetchQuotes(emotion);
  }, [emotion, fetchQuotes]);

  const captureFrame = useCallback(() => {
    if (isWebcamActive && webcamRef.current) {
      const imageSrc = webcamRef.current.getScreenshot();
      if (imageSrc) sendFrame(imageSrc);
    }
  }, [sendFrame, isWebcamActive]);

  useEffect(() => {
    const interval = setInterval(captureFrame, 500);
    return () => clearInterval(interval);
  }, [captureFrame]);

  useEffect(() => {
    if (isWebcamActive && (liveEmotion === 'angry' || liveEmotion === 'fear')) {
      if (!stressTimerRef.current) {
        stressTimerRef.current = setTimeout(() => setShowBreathingGuide(true), 5000);
      }
    } else {
      if (stressTimerRef.current) clearTimeout(stressTimerRef.current);
      stressTimerRef.current = null;
    }
    return () => { if (stressTimerRef.current) clearTimeout(stressTimerRef.current); };
  }, [liveEmotion, isWebcamActive]);
  
  const currentStyle = emotionStyles[emotion] || emotionStyles.neutral;

  return (
    <>
      <AnimatePresence>
        {apiStatus === 'offline' && (
            <motion.div 
              className="absolute top-6 left-1/2 -translate-x-1/2 z-50 flex items-center gap-3 rounded-lg bg-yellow-500/90 px-4 py-2 text-black shadow-lg"
              initial={{ y: -100, opacity: 0 }}
              animate={{ y: 0, opacity: 1 }}
              exit={{ y: -100, opacity: 0 }}
            >
                 <AlertTriangle size={16} />
                 <span className="text-sm font-medium">Quote API offline. Using local fallbacks.</span>
            </motion.div>
        )}
      </AnimatePresence>

      <main className="relative min-h-screen w-full overflow-hidden bg-gray-900 text-white transition-colors duration-[2000ms]">
        {hasMounted && <motion.svg width="100%" height="100%" className="absolute inset-0 z-0 opacity-30">{[...Array(50)].map((_, i) => <Particle key={i} />)}</motion.svg>}
        <motion.div className="absolute inset-0 z-0" animate={{ background: `radial-gradient(ellipse at 40% 60%, ${currentStyle.auroraColors[0]} 0%, transparent 50%), radial-gradient(ellipse at 60% 40%, ${currentStyle.auroraColors[1]} 0%, transparent 50%)` }} transition={{ duration: 2.0, ease: "easeInOut" }} />

        <div className="relative z-10 flex h-screen flex-col items-center p-4">
          <header className="absolute top-0 left-0 w-full p-6 flex justify-between items-center">
             <h1 className="text-xl font-bold tracking-wider">MindMorph</h1>
             <div className="flex items-center gap-4 text-gray-400">
                <button title="Get New Quote" onClick={() => fetchQuotes(emotion)} className="hover:text-white transition-colors"><RefreshCw size={20} className={isQuoteLoading ? 'animate-spin' : ''} /></button>
                <button title="Breathing Exercise" onClick={() => setShowBreathingGuide(true)} className="hover:text-white transition-colors"><Wind size={20}/></button>
                <button title="Analytics" onClick={() => console.log("Analytics clicked")} className="hover:text-white transition-colors"><BarChart size={20}/></button>
                <button title="Journal" onClick={() => console.log("Journal clicked")} className="hover:text-white transition-colors"><MessageSquare size={20}/></button>
                <button title="Settings" onClick={() => console.log("Settings clicked")} className="hover:text-white transition-colors"><Sliders size={20}/></button>
             </div>
          </header>

          <div className="flex flex-1 flex-col items-center justify-center text-center -mt-16">
            <motion.div
              className="mb-8 h-48 w-48 rounded-full flex items-center justify-center shadow-lg"
              style={{ background: `radial-gradient(circle at center, ${currentStyle.orbColor} 0%, transparent 70%)` }}
              animate={{ scale: [1, 1.05, 1], transition: { duration: 4, repeat: Infinity, ease: 'easeInOut' } }}
            >
              <span className="text-3xl font-bold capitalize">{emotion}</span>
            </motion.div>
            
            <AnimatedQuote quote={currentQuote.quote} author={currentQuote.author} isLoading={isQuoteLoading} />
          </div>

          <footer className="absolute bottom-0 w-full h-48 flex items-center justify-center">
            <AnimatePresence mode="wait">
              {isWebcamActive ? (
                <motion.div key="webcam-active" className="w-full max-w-xs rounded-2xl border border-white/10 bg-white/5 p-2 backdrop-blur-lg shadow-lg" initial={{opacity: 0, scale: 0.8}} animate={{opacity: 1, scale: 1}} exit={{opacity: 0, scale: 0.8}} transition={{duration: 0.3}} >
                   <div className="relative aspect-video w-full overflow-hidden rounded-lg">
                     <Webcam ref={webcamRef} mirrored={true} className="h-full w-full object-cover" videoConstraints={{ width: 320, height: 180, facingMode: "user" }} />
                     <div className="absolute top-2 right-2 flex items-center gap-3">
                         <button onClick={() => setIsWebcamActive(false)} className="p-1.5 rounded-full bg-red-500/80 text-white hover:bg-red-600/80 transition-colors"> <VideoOff size={14} /> </button>
                         <div className={`flex items-center gap-2 rounded-full px-2 py-1 text-xs transition-colors ${isConnected ? 'bg-green-500/80' : 'bg-red-500/80'}`}> <Wifi size={12} /> {isConnected ? 'Connected' : 'Offline'} </div>
                     </div>
                   </div>
                </motion.div>
              ) : (
                <motion.div key="dashboard-inactive" className="w-full h-full relative" initial={{ opacity: 0 }} animate={{ opacity: 1, transition: { delay: 0.3 } }} exit={{ opacity: 0 }}>
                    <DailyIntention />
                    <EmotionSimulator onSelect={setSimulatedEmotion} activeEmotion={simulatedEmotion} />
                    
                    <div className="absolute bottom-8 right-8">
                         <button onClick={() => setIsWebcamActive(true)} className="w-20 h-20 rounded-full bg-white/10 border border-white/20 backdrop-blur-lg flex items-center justify-center text-white/70 hover:text-white hover:bg-white/20 transition-all duration-300">
                             <motion.div animate={{ scale: [1, 1.1, 1]}} transition={{ duration: 2, repeat: Infinity, ease: 'easeInOut' }}>
                                 <Zap size={28} />
                             </motion.div>
                         </button>
                    </div>
                </motion.div>
              )}
            </AnimatePresence>
          </footer>
        </div>
      </main>
      
      <BreathingGuide isVisible={showBreathingGuide} onClose={() => setShowBreathingGuide(false)} />
    </>
  );
}

